INSERT INTO "Post" ("id", "title", "slug", "excerpt", "content", "image", "published", "publishedAt", "createdAt", "updatedAt") VALUES ('cmudlppro000numgosojh7paz', 'What to look for beyond the brochure', 'beyond-the-brochure', 'A practical guide to evaluating a property beyond photographs and marketing language.', 'Location, access, documentation, infrastructure and exit potential should all form part of a serious property assessment.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1400&q=85', TRUE, '2026-10-20 13:25:33.802', '2026-09-23 03:26:52.213', '2026-10-20 13:25:33.805');
