INSERT INTO "Post" ("id", "title", "slug", "excerpt", "content", "image", "published", "publishedAt", "createdAt", "updatedAt") VALUES ('cmudlpps3000pumgokgyomp6p', 'Designing a home around how you live', 'designing-around-how-you-live', 'Why good residential design starts with daily rituals, not room counts.', 'The best homes make everyday routines feel simpler and more generous.', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1400&q=85', TRUE, '2026-10-18 13:25:33.802', '2026-09-23 03:26:52.228', '2026-10-20 13:25:33.820');


